import { setThemePreferences, settleTheme } from "../helpers/theme-preferences";
import { test as base } from "../helpers/system-control-browser";
import "dotenv/config";
import { expect, type Page } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import { Pool } from "pg";
import { randomUUID } from "node:crypto";
import { encode } from "next-auth/jwt";
import { encryptToken } from "../../src/lib/crypto";
import { requireTestDatabaseUrl } from "../helpers/foundation-db";
import { mkdirSync, writeFileSync } from "node:fs";

const themes = [
  ["Lavender Light", "purple", "light"],
  ["Nightbloom Dark", "purple", "dark"],
  ["Chalk Light", "vercel", "light"],
  ["Obsidian Dark", "vercel", "dark"],
] as const;
const routes = [
  "compose",
  "templates",
  "contacts",
  "usage",
  "history",
  "settings",
];
// Only semantic primitives shared by every workspace page belong at root scope.
// Scoped palette references are checked against their actual consumers below.
const primitives = [
  "--background",
  "--foreground",
  "--border",
  "--body",
  "--link",
  "--ring",
];
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});
const test = base.extend<{ auditUser: string }>({
  auditUser: async ({ context }, runFixture) => {
    if (process.env.MAILLOOP_E2E_ISOLATED !== "1")
      throw new Error("Run using the disposable database runner.");
    requireTestDatabaseUrl();
    await pool.query(
      `UPDATE "SystemControl" SET "paidGatingEnabled"=true WHERE key='global'`,
    );
    const id = randomUUID();
    await pool.query(
      `INSERT INTO "User" (id,email,name,"googleId","gmailAuthorized","encryptedRefreshToken","gmailScopes","gmailSendOnlyConsentAt","usageBackfillVersion","usageCutoverAt") VALUES ($1,$2,'Theme audit',$1,true,$3,ARRAY['openid','email','profile','https://www.googleapis.com/auth/gmail.send'],NOW(),1,NOW())`,
      [
        id,
        "[REDACTED_EMAIL]",
        encryptToken("FAKE-BROWSER-TEST-TOKEN", id),
      ],
    );
    await pool.query(
      `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW(),"planOverrideReason"='Theme fixture' WHERE id=$1`,
      [id],
    );
    const salt = "authjs.session-token";
    const token = await encode({
      secret: process.env.AUTH_SECRET!,
      salt,
      token: {
        userId: id,
        sub: id,
        name: "Theme audit",
        email: "[REDACTED_EMAIL]",
      },
    });
    await context.addCookies([
      {
        name: salt,
        value: token,
        domain: "localhost",
        path: "/",
        httpOnly: true,
        sameSite: "Lax",
        expires: Date.now() / 1000 + 3600,
      },
    ]);
    try {
      await runFixture(id);
    } finally {
      await pool.query('DELETE FROM "Campaign" WHERE "userId"=$1', [id]);
      await pool.query('DELETE FROM "User" WHERE id=$1', [id]);
    }
  },
});
test.skip(
  process.env.MAILLOOP_E2E_ISOLATED !== "1",
  "Run npm run test:themes with its disposable database.",
);
test.afterAll(async () => {
  await pool.end();
});
async function choose(page: Page, label: string) {
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page.getByRole("menuitemradio", { name: label, exact: true }).click();
}

// Measurements are findings, not a waiver of the requested thresholds. Complex
// backgrounds are explicitly flagged for visual review instead of invented ratios.
async function measure(page: Page) {
  return page.evaluate((names) => {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1;
    const ctx = canvas.getContext("2d", { willReadFrequently: true })!;
    function rgba(value: string): number[] {
      ctx.clearRect(0, 0, 1, 1);
      ctx.fillStyle = value;
      ctx.fillRect(0, 0, 1, 1);
      return Array.from(ctx.getImageData(0, 0, 1, 1).data).map((v, i) =>
        i === 3 ? v / 255 : v,
      );
    }
    function over(f: number[], b: number[]) {
      return [0, 1, 2].map((i) => f[i] * f[3] + b[i] * (1 - f[3])).concat(1);
    }
    function luminance(c: number[]) {
      return c
        .slice(0, 3)
        .map((v) => {
          v /= 255;
          return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
        })
        .reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
    }
    function ratio(a: number[], b: number[]) {
      const x = luminance(a),
        y = luminance(b);
      return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
    }
    const records: Array<{
        ratio: number | null;
        threshold: number;
        [key: string]: unknown;
      }> = [],
      missing: object[] = [],
      neutral: object[] = [];
    const elements = Array.from(
      document.querySelectorAll<HTMLElement>("body *"),
    );
    for (const el of elements) {
      const cs = getComputedStyle(el),
        box = el.getBoundingClientRect();
      if (
        !box.width ||
        !box.height ||
        cs.visibility === "hidden" ||
        el.closest("[inert]") ||
        el.closest(':disabled, [aria-disabled="true"]')
      )
        continue;
      const chain: HTMLElement[] = [];
      let parent: HTMLElement | null = el;
      while (parent) {
        chain.unshift(parent);
        parent = parent.parentElement;
      }
      let backgrounds = [[255, 255, 255, 1]],
        opacity = 1,
        complex = false;
      const images: string[] = [];
      let exterior = backgrounds;
      // Split only top-level commas: the first CSS image is painted last.
      function layers(value: string) {
        const result: string[] = [];
        let depth = 0,
          start = 0;
        for (let i = 0; i < value.length; i++) {
          if (value[i] === "(") depth++;
          if (value[i] === ")") depth--;
          if (value[i] === "," && depth === 0) {
            result.push(value.slice(start, i));
            start = i + 1;
          }
        }
        result.push(value.slice(start));
        return result;
      }
      function gradientColors(value: string) {
        return (
          value.match(/(?:rgba?\([^)]*\)|color\([^)]*\)|oklch\([^)]*\))/g) ?? []
        ).map(rgba);
      }
      let textPaint: number[][] | undefined;
      for (const ancestor of chain) {
        const style = getComputedStyle(ancestor);
        if (ancestor === el) exterior = backgrounds;
        const layer = rgba(style.backgroundColor);
        if (layer[3] === 1) complex = false;
        backgrounds =
          layer[3] === 1 ? [layer] : backgrounds.map((bg) => over(layer, bg));
        opacity *= Number(style.opacity);
        if (
          style.backgroundClip === "text" &&
          style.backgroundImage !== "none"
        ) {
          textPaint = gradientColors(style.backgroundImage);
          continue;
        }
        for (const img of layers(style.backgroundImage).reverse()) {
          if (img.trim() === "none") continue;
          images.push(img);
          // A radial decoration varies by position. Its full color range cannot
          // stand in for the background beneath this text; retain it for review.
          const radial = img.includes("radial-gradient(");
          const stops = gradientColors(img);
          if (stops.length && !img.includes("url(")) {
            const samples = [...stops];
            for (let i = 1; i < stops.length; i++) {
              const a = stops[i - 1],
                b = stops[i];
              // CSS interpolates translucent stops with premultiplied alpha.
              // Straight RGB interpolation invents bright gray between a faint
              // white stop and an opaque dark stop, overstating the background.
              for (let step = 1; step < 20; step++) {
                const t = step / 20;
                const alpha = a[3] * (1 - t) + b[3] * t;
                samples.push(
                  [0, 1, 2]
                    .map((channel) =>
                      alpha
                        ? (a[channel] * a[3] * (1 - t) +
                            b[channel] * b[3] * t) /
                          alpha
                        : 0,
                    )
                    .concat(alpha),
                );
              }
            }
            if (samples.every((sample) => sample[3] === 1)) complex = false;
            if (radial) complex = true;
            backgrounds = backgrounds.flatMap((bg) =>
              samples.map((sample) => over(sample, bg)),
            );
            if (backgrounds.length > 500)
              backgrounds = backgrounds.filter(
                (_, i) => i % Math.ceil(backgrounds.length / 500) === 0,
              );
          } else complex = true;
        }
      }
      const bg = backgrounds[0];
      function worstBackground(ink: number[]) {
        return backgrounds.reduce((worst, candidate) =>
          ratio(over(ink, candidate), candidate) <
          ratio(over(ink, worst), worst)
            ? candidate
            : worst,
        );
      }
      function worst(ink: number[]) {
        return Math.min(...backgrounds.map((bg) => ratio(over(ink, bg), bg)));
      }
      const text = Array.from(el.childNodes)
        .filter((n) => n.nodeType === Node.TEXT_NODE)
        .map((n) => n.textContent)
        .join("")
        .trim();
      if (text || el.matches("input,textarea,select")) {
        const paints = textPaint?.length ? textPaint : [rgba(cs.color)];
        const fg = paints[0];
        fg[3] *= opacity;
        const large =
          parseFloat(cs.fontSize) >= 24 ||
          (parseFloat(cs.fontSize) >= 18.66 && Number(cs.fontWeight) >= 700);
        const threshold = large ? 3 : 4.5;
        records.push({
          element: el.tagName + "." + el.className,
          text: text.slice(0, 70),
          foreground: cs.color,
          background: worstBackground(fg),
          opacity,
          threshold,
          ratio: complex
            ? null
            : Math.min(...paints.map((paint) => worst(paint))),
          gradientSamples: backgrounds.length,
          backgroundImages: images,
          complexBackground: complex,
        });
        if (el.matches("input,textarea") && el.getAttribute("placeholder")) {
          const placeholder = getComputedStyle(el, "::placeholder");
          const ink = rgba(placeholder.color);
          ink[3] *= opacity * Number(placeholder.opacity);
          records.push({
            element: el.tagName + "::placeholder",
            foreground: placeholder.color,
            background: worstBackground(ink),
            threshold: 4.5,
            ratio: complex ? null : worst(ink),
          });
        }
      }
      if (
        el.matches(
          "input:not([type=hidden]):not([type=checkbox]):not([type=radio]),select,textarea,html[data-appearance=vercel] .field-focus-wrapper",
        ) &&
        parseFloat(cs.borderTopWidth) > 0 &&
        cs.borderTopStyle !== "none"
      ) {
        const ink = rgba(cs.borderTopColor);
        ink[3] *= opacity;
        records.push({
          element: el.tagName + "." + el.className,
          kind: "control-boundary",
          foreground: cs.borderTopColor,
          background: bg,
          threshold: 3,
          ratio: complex
            ? null
            : Math.max(
                Math.min(...exterior.map((bg) => ratio(over(ink, bg), bg))),
                Math.min(
                  ...exterior.flatMap((outside) =>
                    backgrounds.map((fill) => ratio(fill, outside)),
                  ),
                ),
              ),
          functional:
            "candidate: adjacent exterior background still requires review",
        });
      }
      if (
        el.matches("circle[stroke]") &&
        !/ring-track|usage-line/.test(el.getAttribute("stroke") ?? "") &&
        Number(cs.opacity) > 0
      ) {
        let paints = [cs.stroke];
        if (cs.stroke.startsWith("url(")) {
          const id = cs.stroke.match(/#([^\s"')]+)/)?.[1];
          const gradient = id
            ? document.getElementById(decodeURIComponent(id))
            : null;
          paints = gradient
            ? Array.from(gradient.querySelectorAll("stop")).map(
                (stop) => getComputedStyle(stop).stopColor,
              )
            : [];
        }
        for (const paint of paints.filter((paint) => paint !== "none")) {
          const ink = rgba(paint);
          ink[3] *= opacity * Number(cs.strokeOpacity);
          records.push({
            element: "circle[stroke=" + el.getAttribute("stroke") + "]",
            kind: "progress-indicator",
            foreground: paint,
            background: worstBackground(ink),
            opacity,
            threshold: 3,
            ratio: complex ? null : worst(ink),
          });
        }
      }
      if (
        el.matches(
          '[role="img"] > span[style*="background"],.recipient-meter-fill',
        )
      ) {
        const ink = rgba(cs.backgroundColor);
        if (ink[3] > 0)
          records.push({
            element: el.tagName + "." + el.className,
            kind: "progress-indicator",
            foreground: cs.backgroundColor,
            background: exterior[0],
            threshold: 3,
            ratio: Math.min(...exterior.map((bg) => ratio(over(ink, bg), bg))),
          });
      }
      if (
        el.matches(
          ":focus-visible, .field-focus-wrapper:has(input:focus-visible)",
        ) &&
        cs.outlineStyle !== "none" &&
        parseFloat(cs.outlineWidth) > 0
      ) {
        const ink = rgba(cs.outlineColor);
        records.push({
          element: el.tagName + "." + el.className,
          kind: "focus-indicator",
          foreground: cs.outlineColor,
          background: exterior[0],
          threshold: 3,
          ratio: Math.min(...exterior.map((bg) => ratio(over(ink, bg), bg))),
        });
      }
      // Check variables used by loaded CSS at the actual element scope below.
      if (
        el.matches(
          "main,main>*,.mail-preview,.history-surface,.appearance-menu",
        )
      ) {
        for (const name of names)
          if (!cs.getPropertyValue(name).trim())
            missing.push({ element: el.className, name });
      }
      if (document.documentElement.dataset.appearance === "vercel") {
        for (const name of [
          "--highlight-background",
          "--highlight-foreground",
          "--highlight-border",
          "--link",
          "--ring",
          "--progress-fill",
        ]) {
          const value = cs.getPropertyValue(name).trim();
          if (value) {
            const c = rgba(value);
            if (Math.max(...c.slice(0, 3)) - Math.min(...c.slice(0, 3)) > 2)
              neutral.push({ element: el.className, name, value });
          }
        }
      }
    }
    const unresolved: Array<{
      selector: string;
      name: string;
      hasFallback: boolean;
    }> = [];
    function inspect(rules: CSSRuleList) {
      for (const rule of Array.from(rules)) {
        if (
          rule instanceof CSSMediaRule &&
          !matchMedia(rule.conditionText).matches
        )
          continue;
        if (rule instanceof CSSStyleRule) {
          let matches: Element[] = [];
          try {
            matches = Array.from(document.querySelectorAll(rule.selectorText));
          } catch {
            continue;
          }
          // Palette aliases can be intentionally absent outside their consumer
          // scope. Inspect rendered properties; an invalid alias is still caught
          // when a background, color, border, etc. actually references it.
          const declarations = Array.from(rule.style)
            .filter((property) => !property.startsWith("--"))
            .map((property) => rule.style.getPropertyValue(property))
            .join(";");
          const refs = [
            ...declarations.matchAll(/var\((--[\w-]+)(\s*,)?/g),
          ].map((m) => ({ name: m[1], hasFallback: !!m[2] }));
          for (const el of matches.slice(0, 4)) {
            const cs = getComputedStyle(el);
            for (const ref of refs)
              if (!cs.getPropertyValue(ref.name).trim())
                unresolved.push({ selector: rule.selectorText, ...ref });
          }
        } else if ("cssRules" in rule)
          inspect((rule as CSSGroupingRule).cssRules);
      }
    }
    for (const sheet of Array.from(document.styleSheets)) {
      try {
        inspect(sheet.cssRules);
      } catch {
        /* cross-origin sheet */
      }
    }
    return {
      records,
      missing,
      neutral,
      unresolved,
      layout: {
        viewportWidth: innerWidth,
        scrollWidth: document.documentElement.scrollWidth,
        horizontalOverflow: Math.max(
          0,
          document.documentElement.scrollWidth - innerWidth,
        ),
      },
    };
  }, primitives);
}

for (const state of ["empty-free", "populated-premium"]) {
  test(`four-theme audit: ${state}`, async ({ page, auditUser }, info) => {
    test.skip(
      info.project.name !== "desktop",
      "Matrix owns its explicit viewport widths.",
    );
    test.setTimeout(900000);
    await pool.query(
      `UPDATE "User" SET "planOverride"=$2::"Plan" WHERE id=$1`,
      [auditUser, state === "empty-free" ? "FREE" : "PAID"],
    );
    if (state === "populated-premium") {
      await pool.query(
        `UPDATE "User" SET "planOverride"='PAID',"planOverrideStartsAt"=NOW()-interval '1 day',"planOverrideReason"='Theme audit fixture' WHERE id=$1`,
        [auditUser],
      );
      const template = randomUUID(),
        contact = randomUUID(),
        campaign = randomUUID();
      await pool.query(
        `INSERT INTO "Template" (id,"userId",name,subject,body) VALUES ($1,$2,'Engineering introduction','Hello {{name}}','Hello {{name}}, I would love to join {{company}} as {{role}}.')`,
        [template, auditUser],
      );
      await pool.query(
        `INSERT INTO "Contact" (id,"userId",name,email,company,"jobRole") VALUES ($1,$2,'Ada Example','[REDACTED_EMAIL]','Example Company','Engineer')`,
        [contact, auditUser],
      );
      await pool.query(
        `INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ($1,$2,$3,'COMPLETED')`,
        [campaign, auditUser, template],
      );
      const daily = randomUUID(),
        monthly = randomUUID();
      for (const [id, kind, unit, prefix] of [
        [daily, "DAILY", "day", "day:"],
        [monthly, "MONTHLY", "month", "month:"],
      ]) {
        await pool.query(
          `INSERT INTO "UsagePeriod" (id,"userId",key,kind,"startsAt","endsAt","operationalEndsAt") VALUES ($1,$2,$3 || to_char(date_trunc($4,now() AT TIME ZONE 'UTC'),'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),$5::"UsagePeriodKind",date_trunc($4,now() AT TIME ZONE 'UTC'),date_trunc($4,now() AT TIME ZONE 'UTC')+('1 ' || $4)::interval,date_trunc($4,now() AT TIME ZONE 'UTC')+('1 ' || $4)::interval)`,
          [id, auditUser, prefix, unit, kind],
        );
      }
      for (const status of ["SENT", "QUEUED", "FAILED", "REPLIED"]) {
        const send = randomUUID();
        await pool.query(
          `INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","recipientName","recipientEmail","recipientCompany","recipientRole","templateName",subject,body,"sentAt") VALUES ($1,$2,$3,$4::"SendStatus",$5::"DeliveryState",'Ada Example','[REDACTED_EMAIL]','Example Company','Engineer','Engineering introduction','Hello Ada','Synthetic preview',CASE WHEN $4 IN ('SENT','REPLIED') THEN '2026-10-02T12:00:00Z'::timestamptz ELSE NULL END)`,
          [
            send,
            campaign,
            contact,
            status,
            status === "QUEUED" ? "READY" : "DONE",
          ],
        );
        if (status === "QUEUED") {
          await pool.query(
            `INSERT INTO "UsageReservation" (id,"userId","deliveryKey","sendId","dailyPeriodId","monthlyPeriodId",status,"chargedAt") VALUES ($1,$2,$3,$3,$4,$5,'RESERVED',NULL)`,
            [randomUUID(), auditUser, send, daily, monthly],
          );
        } else if (status === "SENT" || status === "REPLIED") {
          await pool.query(
            `INSERT INTO "UsageImportEvidence" (id,"userId","sourceKey","deliveryKey","chargedAt","timestampSource") VALUES ($1,$2,$3,$3,'2026-10-02T12:00:00Z','sentAt')`,
            [randomUUID(), auditUser, send],
          );
        }
      }
    }
    // Keep reset labels fixed across calendar days; the API's counts/access still
    // come from this disposable user's real fixture data.
    await page.route("**/api/quota", async (route) => {
      const response = await route.fetch();
      const quota = await response.json();
      if (quota.mode === "gated") {
        Object.assign(quota.daily, {
          startsAt: "2026-11-02T00:00:00.000Z",
          endsAt: "2026-11-03T00:00:00.000Z",
          resetsAt: "2026-11-03T00:00:00.000Z",
        });
        Object.assign(quota.monthly, {
          startsAt: "2026-11-01T00:00:00.000Z",
          endsAt: "2026-12-01T00:00:00.000Z",
          resetsAt: "2026-12-01T00:00:00.000Z",
        });
      }
      await route.fulfill({ response, json: quota });
    });
    await page.emulateMedia({ reducedMotion: "reduce" });
    const results = [];
    for (const [label, appearance, mode] of state === "empty-free"
      ? themes.slice(0, 2)
      : themes) {
      await setThemePreferences(page, appearance, mode);
      for (const route of routes) {
        await page.setViewportSize({ width: 1440, height: 1000 });
        console.log(`Auditing ${state}: ${label} / ${route}`);
        await page.goto(`/${route}`, { timeout: 45000 });
        await expect(page.locator("html")).toHaveAttribute(
          "data-appearance",
          appearance,
        );
        await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
        await expect(page.locator("main")).toHaveCount(1);
        await expect(page.locator("main h1")).toBeVisible();
        await expect(
          page.locator('[role="status"][aria-busy="true"]'),
        ).toHaveCount(0);
        await settleTheme(page);
        await page.waitForFunction(
          () =>
            Object.keys(
              document.querySelector(".appearance-trigger") ?? {},
            ).some((key) => key.startsWith("__reactProps")),
          undefined,
          { timeout: 10000 },
        );
        if (route === "usage") {
          // This fixture changes only quota dates. An access refresh also
          // refreshes the server tree, racing its real dates against the mock.
          await Promise.all([
            page.waitForResponse(
              (response) => response.url().endsWith("/api/quota") && response.ok(),
            ),
            page.evaluate(() => window.dispatchEvent(new Event("focus"))),
          ]);
          await expect(
            page
              .getByRole("region", { name: "Daily allowance", exact: true })
              .locator("time")
              .first(),
          ).toHaveAttribute("datetime", "2026-11-03T00:00:00.000Z");
        }
        await expect
          .soft(page)
          .toHaveScreenshot(`${state}-${appearance}-${mode}-${route}.png`, {
            fullPage: true,
            caret: "initial",
            animations: "disabled",
            maxDiffPixelRatio: 0.005,
            stylePath: "tests/helpers/screenshot.css",
            mask: [page.locator(".workspace-account-menu")],
          });
        const colors = await measure(page);
        const axe = await new AxeBuilder({ page }).analyze();
        results.push({
          theme: label,
          route,
          state,
          width: 1440,
          ...colors,
          axe: axe.violations,
        });
        mkdirSync("test-results/theme-audit/artifacts", { recursive: true });
        writeFileSync(
          `test-results/theme-audit/artifacts/${state}.json`,
          JSON.stringify(results, null, 2),
        );
        expect
          .soft(
            colors.records.filter(
              (record) =>
                record.ratio !== null && record.ratio < record.threshold,
            ),
            `${label}/${route}: contrast`,
          )
          .toEqual([]);
        expect.soft(axe.violations, `${label}/${route}: axe`).toEqual([]);
        expect
          .soft(
            colors.unresolved.filter(
              (ref) => !ref.hasFallback && !ref.name.startsWith("--tw-"),
            ),
            `${label}/${route}: unresolved used variable`,
          )
          .toEqual([]);
        expect
          .soft(
            colors.layout.horizontalOverflow,
            `${label}/${route}: horizontal overflow`,
          )
          .toBe(0);
        expect
          .soft(colors.missing, `${label}/${route}: missing primitive`)
          .toEqual([]);
        expect
          .soft(colors.neutral, `${label}/${route}: chromatic neutral token`)
          .toEqual([]);
        for (const width of [1440, 1024, 768, 661, 660, 659, 390, 320]) {
          await page.setViewportSize({ width, height: 1000 });
          if (width !== 1440) {
            const responsive = await measure(page);
            expect
              .soft(
                responsive.layout.horizontalOverflow,
                `${label}/${route}/${width}: horizontal overflow`,
              )
              .toBe(0);
            expect
              .soft(
                responsive.unresolved.filter(
                  (ref) => !ref.hasFallback && !ref.name.startsWith("--tw-"),
                ),
                `${label}/${route}/${width}: unresolved used variable`,
              )
              .toEqual([]);
            results.push({
              theme: label,
              route,
              state: `${state}/${width}px`,
              width,
