test("four-theme audit: single field outline", async ({
  page,
  auditUser,
}, info) => {
  void auditUser;
  const previous = await pool.query(
    `SELECT "paidGatingEnabled" FROM "SystemControl" WHERE key='global'`,
  );
  await pool.query(
    `INSERT INTO "SystemControl" (id,key,"paidGatingEnabled","updatedAt")
     VALUES ($1,'global',true,NOW()) ON CONFLICT (key)
     DO UPDATE SET "paidGatingEnabled"=true`,
    [randomUUID()],
  );
  test.setTimeout(180000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  try {
    for (const [label, appearance, mode] of themes) {
      await setThemePreferences(page, appearance, mode);
      for (const route of [
        "contacts",
        "compose",
        "templates",
        "templates?new=1",
        "history",
        "settings",
        "billing",
      ]) {
        await page.goto(`/${route}`);
        await expect(page.locator("html")).toHaveAttribute(
          "data-appearance",
          appearance,
        );
        await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
        const fields = page.locator(
          'main :is(input:not([type="hidden"], [type="checkbox"], [type="radio"], [type="file"]), textarea, select):visible:enabled',
        );
        // Billing currently exposes links and buttons, rather than editable fields.
        if (route !== "billing")
          await expect(fields.first(), `${label}: ${route}`).toBeVisible();
        await page.keyboard.press("Tab");
        for (const field of await fields.all()) {
          const before = await field.evaluate((el) => {
            const cs = getComputedStyle(el);
            return {
              border: cs.borderColor,
              width: cs.borderWidth,
              radius: cs.borderRadius,
            };
          });
          await field.focus();
          await expect(field).toBeFocused();
          const wrapper = field.locator(
            'xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " field-focus-wrapper ")]',
          );
          const wrapped = (await wrapper.count()) > 0;
          const indicator = wrapped ? wrapper : field;
          await expect(indicator).toHaveCSS("outline-style", "solid");
          await expect(indicator).toHaveCSS("outline-width", "2px");
          await expect(indicator).toHaveCSS("outline-offset", "2px");
          await expect(indicator).toHaveCSS("box-shadow", "none");
          await expect(field).toHaveCSS("box-shadow", "none");
          await expect(field).toHaveCSS("border-color", before.border);
          await expect(field).toHaveCSS("border-width", before.width);
          await expect(field).toHaveCSS("border-radius", before.radius);
          if (wrapped) await expect(field).toHaveCSS("outline-style", "none");
          const colors = await indicator.evaluate((el) => {
            const cs = getComputedStyle(el);
            const probe = document.createElement("span");
            probe.style.outlineColor = cs.getPropertyValue("--ring");
            document.body.append(probe);
            const colors = {
              actual: cs.outlineColor,
              expected: getComputedStyle(probe).outlineColor,
            };
            probe.remove();
            return colors;
          });
          expect(colors.actual, `${label}: ${route}`).toBe(colors.expected);
        }
        if (route === "contacts") {
          const email = page.getByLabel("Email", { exact: true });
          await email.fill("czarl6");
          await email.click();
          await expect(email).toHaveCSS("outline-style", "solid");
          await page.screenshot({
            path: info.outputPath(`${appearance}-${mode}-contact-focus.png`),
            fullPage: true,
          });
          // Check CSS validation state without submitting or saving fixture data.
          await email.evaluate((el) => el.setAttribute("aria-invalid", "true"));
          await email.blur();
          const errorBorder = await email.evaluate(
            (el) => getComputedStyle(el).borderColor,
          );
          await email.focus();
          await expect(email).toHaveCSS("border-color", errorBorder);
          await expect(email).toHaveCSS("outline-style", "solid");
          await expect(email).toHaveCSS("box-shadow", "none");
          await email.fill("");
        }
      }
    }
  } finally {
    await pool.query(
      `UPDATE "SystemControl" SET "paidGatingEnabled"=$1 WHERE key='global'`,
      [previous.rows[0]?.paidGatingEnabled ?? false],
    );
  }
});

